//! Hosts store: reads and writes the list of SSH hosts as `hosts.toml` in the
//! OS config directory. This module is intentionally thin — it only does
//! serialization and file I/O; no SSH or product logic lives here.

use std::fs;
use std::fs::File;
use std::io::Write;
use std::path::PathBuf;
use std::str::FromStr;

use serde::{Deserialize, Serialize};
use tauri::{AppHandle, Manager};
use tauri_plugin_fs::{FilePath, FsExt};

/// A single SSH host entry. `id` is generated by the backend on `add_host` so
/// the frontend has a stable key for update/delete; everything else is
/// user-supplied.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Host {
    #[serde(default)]
    pub id: String,
    pub name: String,
    pub hostname: String,
    #[serde(default = "default_port")]
    pub port: u16,
    #[serde(default)]
    pub user: String,
    /// Path to a private key on disk. We store the path only — never the key
    /// contents (see CLAUDE.md rules).
    ///
    /// Android exception: the system file picker returns a one-shot `content://`
    /// URI that can't be reopened on a later launch, so there is no stable path
    /// to reference. When one is saved we copy the key once into app-private,
    /// sandboxed storage (see `import_identity_if_uri`) and store *that* path
    /// instead. Desktop is unchanged — a real path is referenced, never copied.
    #[serde(default)]
    pub identity_file: Option<String>,
    #[serde(default)]
    pub tags: Vec<String>,
    #[serde(default)]
    pub notes: String,
}

fn default_port() -> u16 {
    22
}

/// On-disk shape of `hosts.toml`: a single `[[hosts]]` array of tables.
#[derive(Debug, Default, Serialize, Deserialize)]
struct HostsFile {
    #[serde(default)]
    hosts: Vec<Host>,
}

/// Resolve `<app config dir>/hosts.toml`, creating the directory if needed.
/// Resolving the path in Rust (rather than via a JS plugin call) means no
/// extra capability grant is required.
fn hosts_path(app: &AppHandle) -> Result<PathBuf, String> {
    let dir = app
        .path()
        .app_config_dir()
        .map_err(|e| format!("could not resolve config dir: {e}"))?;
    fs::create_dir_all(&dir).map_err(|e| format!("could not create config dir: {e}"))?;
    Ok(dir.join("hosts.toml"))
}

/// Look up a single host by id. Used by the SSH layer to resolve a connection
/// target. Returns `Ok(None)` when no host has that id.
pub fn get_host(app: &AppHandle, id: &str) -> Result<Option<Host>, String> {
    Ok(load(app)?.into_iter().find(|h| h.id == id))
}

/// Load all hosts. A missing file is treated as an empty list (first run).
pub(crate) fn load(app: &AppHandle) -> Result<Vec<Host>, String> {
    let path = hosts_path(app)?;
    if !path.exists() {
        return Ok(Vec::new());
    }
    let text = fs::read_to_string(&path).map_err(|e| format!("could not read {path:?}: {e}"))?;
    let parsed: HostsFile =
        toml::from_str(&text).map_err(|e| format!("could not parse hosts.toml: {e}"))?;
    Ok(parsed.hosts)
}

/// Persist the full list atomically: write to a temp file in the same
/// directory, flush it to disk, back up the previous version, then rename the
/// temp over the target. A crash can therefore never leave a half-written
/// hosts.toml — either the old file or the complete new one is in place.
pub(crate) fn save(app: &AppHandle, hosts: &[Host]) -> Result<(), String> {
    let path = hosts_path(app)?;
    let file = HostsFile {
        hosts: hosts.to_vec(),
    };
    let text = toml::to_string_pretty(&file).map_err(|e| format!("could not serialize: {e}"))?;

    // Write the new content to a sibling temp file. Keeping it in the same
    // directory guarantees the later rename stays on one filesystem, which is
    // what makes that rename atomic.
    let tmp = path.with_extension("toml.tmp");
    {
        let mut f = File::create(&tmp).map_err(|e| format!("could not create {tmp:?}: {e}"))?;
        f.write_all(text.as_bytes())
            .map_err(|e| format!("could not write {tmp:?}: {e}"))?;
        // Flush OS buffers to disk before the rename so the renamed file is
        // guaranteed to hold the full contents.
        f.sync_all()
            .map_err(|e| format!("could not flush {tmp:?}: {e}"))?;
    }

    // Preserve the previous version as hosts.toml.bak before replacing it.
    if path.exists() {
        let bak = path.with_extension("toml.bak");
        fs::copy(&path, &bak).map_err(|e| format!("could not back up to {bak:?}: {e}"))?;
    }

    // Atomic replace: on both Windows and Unix this swaps the target in place.
    fs::rename(&tmp, &path).map_err(|e| format!("could not replace {path:?}: {e}"))
}

/// Directory holding private keys copied into app-private storage. On Android
/// this is the app's sandboxed data dir — not readable by other apps or the
/// user's file browser, and protected by the device's full-disk encryption.
fn keys_dir(app: &AppHandle) -> Result<PathBuf, String> {
    let dir = app
        .path()
        .app_data_dir()
        .map_err(|e| format!("could not resolve data dir: {e}"))?
        .join("keys");
    fs::create_dir_all(&dir).map_err(|e| format!("could not create keys dir: {e}"))?;
    Ok(dir)
}

/// True for a picker handle that isn't a real filesystem path. Android's file
/// picker returns these; desktop pickers always return plain paths.
fn is_picker_uri(s: &str) -> bool {
    s.starts_with("content://") || s.starts_with("file://")
}

/// Whether `path` is a key we previously copied into app-private storage (so
/// deleting it when it's no longer referenced is safe — we own it).
fn is_imported_key(app: &AppHandle, path: &str) -> bool {
    keys_dir(app)
        .map(|dir| PathBuf::from(path).starts_with(&dir))
        .unwrap_or(false)
}

/// If `identity` is a freshly-picked key URI, copy it into app-private storage
/// and return the internal path to store; otherwise return it unchanged.
///
/// Android's picker hands back a one-shot `content://` URI that can't be
/// reopened on a later launch, so we read it **now**, while it's still readable,
/// via the fs plugin (its Android backend resolves the URI through
/// `ContentResolver`) and keep a private copy that `load_secret_key` can read on
/// every connect. The copy is keyed by host id, so re-picking overwrites it
/// rather than leaving stale files. The exported backup still strips
/// `identity_file`, so this copy's path never leaves the device.
fn import_identity_if_uri(app: &AppHandle, host_id: &str, identity: &str) -> Result<String, String> {
    if !is_picker_uri(identity) {
        return Ok(identity.to_string());
    }
    let fp = FilePath::from_str(identity).expect("FilePath::from_str is infallible");
    let mut bytes = app
        .fs()
        .read(fp)
        .map_err(|e| format!("could not read the selected key: {e}"))?;
    let dest = keys_dir(app)?.join(host_id);
    fs::write(&dest, &bytes).map_err(|e| format!("could not store key: {e}"))?;
    // Best-effort wipe of the in-memory copy of the key material.
    bytes.iter_mut().for_each(|b| *b = 0);
    Ok(dest.to_string_lossy().into_owned())
}

/// Remove a host's imported private-key copy, if any. Best-effort.
fn remove_imported_key(app: &AppHandle, host_id: &str) {
    if let Ok(dir) = keys_dir(app) {
        let _ = fs::remove_file(dir.join(host_id));
    }
}

#[tauri::command]
pub fn list_hosts(app: AppHandle) -> Result<Vec<Host>, String> {
    load(&app)
}

#[tauri::command]
pub fn add_host(app: AppHandle, mut host: Host) -> Result<Host, String> {
    let mut hosts = load(&app)?;
    // Always mint a fresh id server-side; ignore whatever the frontend sent.
    host.id = uuid::Uuid::new_v4().to_string();
    // If the key was picked via Android's file picker (a content:// URI), copy
    // it into app-private storage now and store that path instead.
    if let Some(identity) = host.identity_file.as_deref().filter(|s| !s.is_empty()) {
        host.identity_file = Some(import_identity_if_uri(&app, &host.id, identity)?);
    }
    hosts.push(host.clone());
    save(&app, &hosts)?;
    Ok(host)
}

#[tauri::command]
pub fn update_host(app: AppHandle, mut host: Host) -> Result<Host, String> {
    let mut hosts = load(&app)?;
    let idx = hosts
        .iter()
        .position(|h| h.id == host.id)
        .ok_or_else(|| format!("host {} not found", host.id))?;

    let old_identity = hosts[idx].identity_file.clone();
    // Import a freshly-picked key (content:// URI) into app-private storage.
    if let Some(identity) = host.identity_file.as_deref().filter(|s| !s.is_empty()) {
        host.identity_file = Some(import_identity_if_uri(&app, &host.id, identity)?);
    }
    // Clean up a previously-imported copy we own once it's no longer referenced
    // (the user cleared the key or switched to a different one).
    if let Some(old) = old_identity
        && host.identity_file.as_deref() != Some(old.as_str())
        && is_imported_key(&app, &old)
    {
        let _ = fs::remove_file(&old);
    }

    hosts[idx] = host.clone();
    save(&app, &hosts)?;
    Ok(host)
}

#[tauri::command]
pub fn delete_host(app: AppHandle, id: String) -> Result<(), String> {
    let mut hosts = load(&app)?;
    let before = hosts.len();
    hosts.retain(|h| h.id != id);
    if hosts.len() == before {
        return Err(format!("host {id} not found"));
    }
    save(&app, &hosts)?;
    // Drop the host's imported private-key copy, if it had one.
    remove_imported_key(&app, &id);
    Ok(())
}
